#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import csv,sys
from pathlib import Path
src,dst=map(Path,sys.argv[1:3]);groups={'north':[],'south':[],'other':[]}
with src.open(newline='') as f:
    for r in csv.DictReader(f):groups[r['region'] if r['region'] in ('north','south') else 'other'].append(r)
dst.mkdir(parents=True,exist_ok=True)
for name,rows in groups.items():
    with (dst/(name+'.csv')).open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['id','region','name'],lineterminator='\n');w.writeheader();w.writerows(rows)
PY
